// Distingue tres entradas posibles a este workflow:
//   1. Comando de texto: /corregir <id>, /anular <id>, /deshacer
//   2. Callback de un botón de Construir Pendiente (WF2/WF3): monto:X, cat:Y, fix:campo
//   3. Callback de un botón de Avisar Duplicado (WF4): force:<tx_id>, cancel
//
// Todo termina en una de estas acciones: corregir, anular, deshacer,
// resolver_pendiente, forzar_registro, cancelar.

const s = $json;
const tipo = s.payload?.tipo;
const texto = String(s.payload?.texto || '').trim();

let accion = 'desconocida';
let objetivo = null;
let detalle = {};

if (tipo === 'callback') {
  const data = texto; // en WF1, payload.texto = callback_query.data
  if (data === 'ok') { accion = 'confirmar_pendiente'; }
  else if (data === 'cancel') { accion = 'cancelar'; }
  else if (data.startsWith('monto:')) { accion = 'resolver_pendiente'; detalle = { campo: 'monto', valor: Number(data.slice(6)) }; }
  else if (data.startsWith('cat:')) { accion = 'resolver_pendiente'; detalle = { campo: 'categoria_id', valor: data.slice(4) }; }
  else if (data.startsWith('fix:')) { accion = 'pedir_correccion_campo'; detalle = { campo: data.slice(4) }; }
  else if (data.startsWith('force:')) { accion = 'forzar_registro'; objetivo = data.slice(6); }
  else if (data.startsWith('anularok:')) { accion = 'aplicar_anulacion'; objetivo = data.slice(9); }
  else if (data.startsWith('corrfix:')) { const [, id, campo] = data.split(':'); accion = 'pedir_correccion_campo'; objetivo = id; detalle = { campo }; }
} else {
  const m = texto.match(/^\/(corregir|anular|deshacer)(?:@\w+)?\s*(.*)$/i);
  if (m) {
    const cmd = m[1].toLowerCase();
    const arg = m[2].trim();
    if (cmd === 'corregir') { accion = 'iniciar_correccion'; objetivo = arg || null; }
    else if (cmd === 'anular') { accion = 'anular'; objetivo = arg || null; }
    else if (cmd === 'deshacer') { accion = 'deshacer'; }
  }
}

return [{ json: { ...s, corr: { accion, objetivo, detalle } } }];

// Resuelve el objetivo real de la accion contra los datos leidos.
// Aca es donde se aplican las reglas: /deshacer solo el ultimo propio,
// solo un pendiente abierto por chat, TTL de pendientes, etc.

const s = $('Clasificar Accion').first().json;
const txs = $('Leer Transacciones').all().map(i => i.json).filter(t => t && t.transaccion_id);
const pends = $('Leer Pendientes').all().map(i => i.json).filter(p => p && p.pendiente_id);
const ZONA = 'America/Bogota';
const ahora = DateTime.now().setZone(ZONA);

const chatId = String(s.ctx.telegram_chat_id);
const userId = String(s.ctx.telegram_user_id);

function idCoincide(tx, buscado) {
  if (!buscado) return false;
  const full = String(tx.transaccion_id).trim();
  const corto = full.split('-').pop();
  return full === buscado.trim() || corto === buscado.trim().toUpperCase();
}

const pendienteAbierto = pends.find(p =>
  String(p.telegram_chat_id).trim() === chatId &&
  String(p.estado).trim() === 'abierto'
);
const pendienteExpirado = pendienteAbierto &&
  DateTime.fromISO(String(pendienteAbierto.fecha_expiracion), { zone: ZONA }) < ahora;

let resultado = { ...s.corr, ok: false, mensaje: null, tx: null, pendiente: pendienteAbierto || null };

switch (s.corr.accion) {
  case 'iniciar_correccion': {
    if (!s.corr.objetivo) { resultado.mensaje = 'Usa /corregir <id>. Mira /recientes para ver los códigos.'; break; }
    const tx = txs.find(t => idCoincide(t, s.corr.objetivo) && String(t.estado).trim() === 'activo');
    if (!tx) { resultado.mensaje = `No encontré un movimiento activo con id "${s.corr.objetivo}".`; break; }
    resultado.ok = true; resultado.tx = tx;
    break;
  }
  case 'anular': {
    if (!s.corr.objetivo) { resultado.mensaje = 'Usa /anular <id>. Mira /recientes para ver los códigos.'; break; }
    const tx = txs.find(t => idCoincide(t, s.corr.objetivo) && String(t.estado).trim() === 'activo');
    if (!tx) { resultado.mensaje = `No encontré un movimiento activo con id "${s.corr.objetivo}".`; break; }
    resultado.ok = true; resultado.tx = tx;
    break;
  }
  case 'deshacer': {
    // Solo el mas reciente, del propio usuario, en las ultimas 24h.
    const candidatos = txs
      .filter(t => String(t.estado).trim() === 'activo' && String(t.telegram_user_id).trim() === userId)
      .filter(t => ahora.diff(DateTime.fromISO(String(t.timestamp_registro), { zone: ZONA }), 'hours').hours <= 24)
      .sort((a, b) => new Date(b.timestamp_registro) - new Date(a.timestamp_registro));
    if (!candidatos.length) { resultado.mensaje = 'No hay nada reciente que deshacer.'; break; }
    resultado.ok = true; resultado.tx = candidatos[0];
    break;
  }
  case 'resolver_pendiente':
  case 'confirmar_pendiente':
  case 'pedir_correccion_campo': {
    if (!pendienteAbierto) { resultado.mensaje = 'No tienes ninguna confirmación pendiente activa.'; break; }
    if (pendienteExpirado) { resultado.mensaje = 'Esa confirmación ya venció, reenvía el gasto.'; resultado.expirar = true; break; }
    resultado.ok = true;
    break;
  }
  case 'aplicar_anulacion': {
    const tx = txs.find(t => idCoincide(t, s.corr.objetivo) && String(t.estado).trim() === 'activo');
    if (!tx) { resultado.mensaje = 'Ese movimiento ya no está activo (puede que lo hayas anulado antes).'; break; }
    resultado.ok = true; resultado.tx = tx;
    break;
  }
  case 'forzar_registro': {
    resultado.ok = true; // el tx_id viaja en objetivo, WF4 decide con el contrato pendiente
    break;
  }
  case 'cancelar': {
    resultado.ok = true;
    resultado.pendiente = pendienteAbierto || null;
    break;
  }
  default:
    resultado.mensaje = 'No entendí la instrucción.';
}

return [{ json: { ...s, resolucion: resultado } }];

// Ofrece botones para elegir que corregir del movimiento encontrado.
const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const tx = s.resolucion.tx;
const texto = [
  `Corrigiendo ${tx.transaccion_id}`,
  `${fmt(tx.monto)} — ${tx.categoria || tx.categoria_id} · ${tx.fecha_movimiento}`,
  '',
  '¿Qué campo corrijo?'
].join('\n');
const teclado = { inline_keyboard: [
  [{ text: 'Monto', callback_data: `corrfix:${tx.transaccion_id}:monto` }, { text: 'Categoría', callback_data: `corrfix:${tx.transaccion_id}:categoria_id` }],
  [{ text: 'Fecha', callback_data: `corrfix:${tx.transaccion_id}:fecha_movimiento` }, { text: 'Descripción', callback_data: `corrfix:${tx.transaccion_id}:descripcion` }],
  [{ text: 'Cancelar', callback_data: 'cancel' }]
]};
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto, teclado: JSON.stringify(teclado) } }];

// Anulacion: pide confirmacion explicita antes de aplicar.
const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const tx = s.resolucion.tx;
const texto = `¿Anular ${fmt(tx.monto)} en ${tx.categoria || tx.categoria_id} del ${tx.fecha_movimiento}?`;
const teclado = { inline_keyboard: [[
  { text: 'Sí, anular', callback_data: `anularok:${tx.transaccion_id}` },
  { text: 'No', callback_data: 'cancel' }
]]};
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto, teclado: JSON.stringify(teclado) } }];

// Deshacer: mismo patron, requiere confirmacion (regla §12 del enunciado).
const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const tx = s.resolucion.tx;
const texto = `¿Deshacer tu último movimiento? ${fmt(tx.monto)} en ${tx.categoria || tx.categoria_id} del ${tx.fecha_movimiento}.`;
const teclado = { inline_keyboard: [[
  { text: 'Sí, deshacer', callback_data: `anularok:${tx.transaccion_id}` },
  { text: 'No', callback_data: 'cancel' }
]]};
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto, teclado: JSON.stringify(teclado) } }];

// El usuario resolvio un campo ambiguo del pendiente (monto o categoria
// via boton). Se completa el Contrato.Movimiento guardado y se manda
// a WF4. Si aun falta algo, se vuelve a preguntar (no se re-implementa
// aca: se delega a WF2 reconstruyendo su misma logica de pendiente).

const s = $json;
const p = s.resolucion.pendiente;
let propuesto;
try { propuesto = JSON.parse(p.datos_propuestos || '{}'); } catch (e) { propuesto = {}; }

propuesto[s.corr.detalle.campo] = s.corr.detalle.valor;

// Si el campo resuelto era la unica falta, ya se puede registrar.
const campos = new Set(propuesto.campos_faltantes || []);
campos.delete(s.corr.detalle.campo === 'categoria_id' ? 'categoria' : s.corr.detalle.campo);
propuesto.campos_faltantes = [...campos];
propuesto.requiere_confirmacion = campos.size > 0;

return [{
  json: {
    ...s,
    pendiente_a_consumir: p,
    contrato: propuesto,
    _listo: campos.size === 0
  }
}];

// Aun falta algo: re-preguntar con el mismo patron de WF2.
const s = $json;
const c = s.contrato;
const faltantes = c.campos_faltantes || [];
let pregunta = 'Necesito un dato más.';
let botones = [];

if (faltantes.includes('categoria')) {
  pregunta = `$${(c.monto || 0).toLocaleString('es-CO')} — ¿en qué categoría lo pongo?`;
} else if (faltantes.includes('monto')) {
  pregunta = '¿De cuánto fue?';
}
botones.push({ text: 'Cancelar', callback_data: 'cancel' });

return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: pregunta, teclado: JSON.stringify({ inline_keyboard: [botones] }) } }];

// Reenvia force:<tx_id> a WF4 no aplica: WF4 ya decidio no duplicar.
// Aca 'forzar_registro' se resuelve releyendo el pendiente asociado a
// ese chat y reenviandolo a WF4 con una bandera que salta el chequeo
// de duplicado (WF4 lo detecta por posible_duplicado ya marcado).
const s = $json;
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: 'Entendido, lo registro de todas formas.' } }];

// Marca la transaccion original como 'corregido' o 'anulado' segun
// el verbo, y si es correccion crea la fila nueva enlazada (DEC-006).
// El recalculo de saldos de ambas categorias lo dispara el propio WF4
// al procesar la fila nueva; para la anulacion pura se recalcula aqui
// mismo porque no hay Contrato.Movimiento que mandar a WF4.

const s = $json;
const tx = s.resolucion.tx;
const esAnulacion = true; // esta rama solo se alcanza tras confirmar anularok:<id>

return [{
  json: {
    ...s,
    tx_original: tx,
    nuevo_estado: esAnulacion ? 'anulado' : 'corregido',
    es_anulacion: esAnulacion
  }
}];

// Un evento de Auditoria por cada corregir/anular/deshacer aplicado.
const s = $('Preparar Cambio de Estado').first().json;
const ahora = DateTime.now().setZone('America/Bogota');
const stamp = ahora.toFormat('yyyyLLdd');
const rnd = Math.random().toString(36).slice(2, 6).toUpperCase();
return [{
  json: {
    evento_id: `EV-${stamp}-${rnd}`,
    timestamp: ahora.toISO(),
    correlation_id: s.meta.correlation_id,
    workflow: '06-correcciones',
    ejecucion: String(s.meta.execution_id || ''),
    usuario: String(s.ctx.telegram_user_id ?? ''),
    accion: s.corr.accion,
    resultado: 'ok',
    detalle: `${s.tx_original.transaccion_id} -> ${s.nuevo_estado}`,
    error: '',
    datos_tecnicos: JSON.stringify({ monto: s.tx_original.monto, categoria: s.tx_original.categoria_id })
  }
}];

const s = $('Preparar Cambio de Estado').first().json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const tx = s.tx_original;
const texto = s.es_anulacion
  ? `Movimiento anulado. Recuperaste ${fmt(tx.monto)} en ${tx.categoria || tx.categoria_id}.`
  : `Corregido: ${tx.transaccion_id} ahora está marcado como corregido. Registrá el valor correcto como un nuevo movimiento.`;
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto } }];

// Busca la fila por 'pendiente_id' en 'Pendientes', fusiona los campos
// nuevos sobre la fila existente y arma el rango a actualizar.
// El valor de coincidencia y los campos a cambiar vienen de una forma
// ANIDADA (igual que el nodo nativo original), no de un $json plano.
const HEADERS = ["pendiente_id", "telegram_chat_id", "telegram_message_id", "estado_maquina", "datos_propuestos", "campo_ambiguo", "opciones", "fecha_creacion", "fecha_expiracion", "estado", "correlation_id"];
const MATCH_COL = 'pendiente_id';
const filas = $('Leer Pendientes').all().map(i => i.json);
const valorMatch = $json.pendiente_a_consumir?.pendiente_id;
const camposNuevos = { estado: 'consumido' };
const idx = filas.findIndex(f => String(f[MATCH_COL]).trim() === String(valorMatch).trim());
if (idx === -1) { return { json: { _sin_fila: true } }; }
const filaSheets = idx + 2;
const fusionada = { ...filas[idx], ...camposNuevos };
const valores = HEADERS.map(h => fusionada[h] !== undefined && fusionada[h] !== null ? fusionada[h] : '');
return { json: { fila_sheets: filaSheets, valores } };

// Busca la fila por 'pendiente_id' en 'Pendientes', fusiona los campos
// nuevos sobre la fila existente y arma el rango a actualizar.
// El valor de coincidencia y los campos a cambiar vienen de una forma
// ANIDADA (igual que el nodo nativo original), no de un $json plano.
const HEADERS = ["pendiente_id", "telegram_chat_id", "telegram_message_id", "estado_maquina", "datos_propuestos", "campo_ambiguo", "opciones", "fecha_creacion", "fecha_expiracion", "estado", "correlation_id"];
const MATCH_COL = 'pendiente_id';
const filas = $('Leer Pendientes').all().map(i => i.json);
const valorMatch = $json.resolucion?.pendiente?.pendiente_id;
const camposNuevos = { estado: 'cancelado' };
const idx = filas.findIndex(f => String(f[MATCH_COL]).trim() === String(valorMatch).trim());
if (idx === -1) { return { json: { _sin_fila: true } }; }
const filaSheets = idx + 2;
const fusionada = { ...filas[idx], ...camposNuevos };
const valores = HEADERS.map(h => fusionada[h] !== undefined && fusionada[h] !== null ? fusionada[h] : '');
return { json: { fila_sheets: filaSheets, valores } };

// Busca la fila por 'transaccion_id' en 'Transacciones', fusiona los campos
// nuevos sobre la fila existente y arma el rango a actualizar.
// El valor de coincidencia y los campos a cambiar vienen de una forma
// ANIDADA (igual que el nodo nativo original), no de un $json plano.
const HEADERS = ["transaccion_id", "timestamp_registro", "fecha_movimiento", "ciclo_id", "tipo", "monto", "moneda", "categoria_id", "categoria", "subcategoria", "descripcion", "comercio_proveedor", "metodo_pago", "persona", "origen", "telegram_user_id", "telegram_chat_id", "telegram_message_id", "file_id", "archivo_url_o_referencia", "hash_archivo", "texto_original", "datos_extraidos", "confianza_ia", "requiere_revision", "estado", "posible_duplicado", "transaccion_relacionada", "correlation_id", "notas"];
const MATCH_COL = 'transaccion_id';
const filas = $('Leer Transacciones').all().map(i => i.json);
const valorMatch = $json.tx_original?.transaccion_id;
const camposNuevos = { estado: $json.nuevo_estado };
const idx = filas.findIndex(f => String(f[MATCH_COL]).trim() === String(valorMatch).trim());
if (idx === -1) { return { json: { _sin_fila: true } }; }
const filaSheets = idx + 2;
const fusionada = { ...filas[idx], ...camposNuevos };
const valores = HEADERS.map(h => fusionada[h] !== undefined && fusionada[h] !== null ? fusionada[h] : '');
return { json: { fila_sheets: filaSheets, valores } };

// Arma la fila en el orden EXACTO de columnas de 'Auditoria'.
const HEADERS = ["evento_id", "timestamp", "correlation_id", "workflow", "ejecucion", "usuario", "accion", "resultado", "detalle", "error", "datos_tecnicos"];
const item = $json;
const fila = HEADERS.map(h => item[h] !== undefined && item[h] !== null ? item[h] : '');
return { json: { fila } };

// Traduce el formato {inline_keyboard:[[{text,callback_data}]]}
// (el que arman los Code nodes previos) al formato que espera
// el nodo nativo Telegram: rows[].row.buttons[].additionalFields.
const s = $json;
let filas = [];
if (s.teclado) {
  let ik;
  try { ik = JSON.parse(s.teclado).inline_keyboard; } catch (e) { ik = []; }
  filas = ik.map(fila => ({ row: { buttons: fila.map(b => ({ text: b.text, additionalFields: { callback_data: b.callback_data } })) } }));
}
return [{ json: { ...s, _filas_botones: filas, _con_botones: filas.length > 0 } }];
